class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = [None] * L
        match_count = [0] * n

        # Process 'T' constraints to fix characters
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    pos = i + k
                    char = str2[k]
                    if word[pos] is not None and word[pos] != char:
                        return ""
                    word[pos] = char

        # Initialize match_count for 'F' windows based on fixed characters
        for i in range(n):
            if str1[i] == 'F':
                cnt = 0
                for k in range(m):
                    pos = i + k
                    if word[pos] is not None and word[pos] == str2[k]:
                        cnt += 1
                match_count[i] = cnt
                # If 'T' constraints already force an 'F' window to match str2, it's invalid
                if cnt == m:
                    return ""

        # Greedily fill remaining positions
        for j in range(L):
            if word[j] is not None:
                continue

            # Determine forbidden characters at position j
            forbidden = set()
            start_i = max(0, j - m + 1)
            end_i = min(j, n - 1)
            for i in range(start_i, end_i + 1):
                # If an 'F' window has m-1 matches, the current char cannot complete the match
                if str1[i] == 'F' and match_count[i] == m - 1:
                    forbidden.add(str2[j - i])

            # Pick the lexicographically smallest valid character
            chosen = None
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c not in forbidden:
                    chosen = c
                    break

            if chosen is None:
                return ""

            word[j] = chosen

            # Update match_count for affected 'F' windows
            for i in range(start_i, end_i + 1):
                if str1[i] == 'F':
                    if chosen == str2[j - i]:
                        match_count[i] += 1
                        # Safety check; forbidden logic should prevent this
                        if match_count[i] == m:
                            return ""

        return "".join(word)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        MOD = 10**15 + 7
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(fact[i-1] * i, MOD)

        odds = (n + 1) // 2
        evens = n // 2

        if n % 2 == 0:
            total = fact[n//2] * fact[n//2] * 2
        else:
            total = fact[(n+1)//2] * fact[n//2]

        if k > total:
            return []

        used = [False] * (n + 1)
        result = []
        rem_o = odds
        rem_e = evens

        for pos in range(n):
            if pos == 0:
                for num in range(1, n + 1):
                    if used[num]:
                        continue
                    if num % 2 == 1:  # odd
                        rem_odd_pos = (n - 1) // 2
                        rem_even_pos = (n - 1 + 1) // 2
                        r_o = rem_o - 1
                        r_e = rem_e
                    else:  # even
                        rem_odd_pos = (n - 1 + 1) // 2
                        rem_even_pos = (n - 1) // 2
                        r_o = rem_o
                        r_e = rem_e - 1

                    if r_o == rem_odd_pos and r_e == rem_even_pos:
                        count = fact[r_o] * fact[r_e]
                    else:
                        count = 0

                    if k <= count:
                        result.append(num)
                        used[num] = True
                        if num % 2 == 1:
                            rem_o -= 1
                        else:
                            rem_e -= 1
                        first_parity = num % 2
                        break
                    else:
                        k -= count
            else:
                required_parity = (first_parity + pos) % 2
                remaining = n - 1 - pos
                if remaining == 0:
                    rem_odd_pos = 0
                    rem_even_pos = 0
                else:
                    first_rem_parity = (first_parity + pos + 1) % 2
                    if first_rem_parity == 1:
                        rem_odd_pos = (remaining + 1) // 2
                        rem_even_pos = remaining // 2
                    else:
                        rem_odd_pos = remaining // 2
                        rem_even_pos = (remaining + 1) // 2

                for num in range(1, n + 1):
                    if used[num]:
                        continue
                    if num % 2 == required_parity:
                        r_o = rem_o - (1 if num % 2 == 1 else 0)
                        r_e = rem_e - (1 if num % 2 == 0 else 0)

                        if r_o == rem_odd_pos and r_e == rem_even_pos:
                            count = fact[r_o] * fact[r_e]
                        else:
                            count = 0

                        if k <= count:
                            result.append(num)
                            used[num] = True
                            if num % 2 == 1:
                                rem_o -= 1
                            else:
                                rem_e -= 1
                            break
                        else:
                            k -= count

        return result

