class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        p1, p2, p3 = parts[0], parts[1], parts[2]
        L1, L2, L3 = len(p1), len(p2), len(p3)

        def find_all(sub):
            if not sub:
                return []
            res = []
            start = 0
            while True:
                idx = s.find(sub, start)
                if idx == -1:
                    break
                res.append(idx)
                start = idx + 1
            return res

        A = find_all(p1)
        B = find_all(p2)
        C = find_all(p3)

        min_len = float('inf')
        found = False

        if L2 > 0:
            for j in B:
                if L1 == 0:
                    i = j
                else:
                    idx_i = bisect.bisect_right(A, j - L1) - 1
                    if idx_i < 0:
                        continue
                    i = A[idx_i]

                if L3 == 0:
                    k = j + L2
                else:
                    idx_k = bisect.bisect_left(C, j + L2)
                    if idx_k >= len(C):
                        continue
                    k = C[idx_k]

                length = k + L3 - i
                if length < min_len:
                    min_len = length
                    found = True
        else:
            if L3 > 0:
                for k in C:
                    if L1 == 0:
                        i = k
                    else:
                        idx_i = bisect.bisect_right(A, k - L1) - 1
                        if idx_i < 0:
                            continue
                        i = A[idx_i]
                    length = k + L3 - i
                    if length < min_len:
                        min_len = length
                        found = True
            else:
                if L1 == 0:
                    min_len = 0
                    found = True
                else:
                    if A:
                        min_len = 0
                        found = True
                    else:
                        return -1

        return min_len if found else -1

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        # Precompute solutions[d][exp][target] -> list of r such that (r * 10^exp) % d == target
        # We use period 6 for all d <= 9 as 10^k mod d is periodic with period <= 6
        solutions = [[[[] for _ in range(9)] for _ in range(6)] for _ in range(10)]

        for d in range(1, 10):
            for exp in range(6):
                mul = pow(10, exp, d)
                for target in range(d):
                    for r in range(d):
                        if (r * mul) % d == target:
                            solutions[d][exp][target].append(r)

        # cnt[d][rem][offset] stores count of indices i such that P[i] % d == rem and i % 6 == offset
        cnt = [[[0]*6 for _ in range(9)] for _ in range(10)]
        # Initialize with P[0] = 0 at index 0
        for d in range(1, 10):
            cnt[d][0][0] = 1

        prefix_rem = [0]*10
        ans = 0

        for j in range(n):
            digit = int(s[j])
            # Update prefix remainders for all d
            for d in range(1, 10):
                prefix_rem[d] = (prefix_rem[d] * 10 + digit) % d

            # If the last digit is non-zero, check divisibility
            if digit != 0:
                d = digit
                k = (j + 1) % 6
                for offset in range(6):
                    exp = (k - offset) % 6
                    target = prefix_rem[d]
                    # Add counts of valid starting positions
                    for r in solutions[d][exp][target]:
                        ans += cnt[d][r][offset]

            # Update counts for the current position j+1
            for d in range(1, 10):
                cnt[d][prefix_rem[d]][(j + 1) % 6] += 1

        return ans

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        def check(x):
            total = 0
            for p in points:
                total += (x + p - 1) // p
                if total > m:
                    return False
            return True

        low, high = 0, m * max(points)
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

