                else:
                    val1 = curr_dp[i + 1]
                    val2 = next_dp[i]
                    next_dp[i + 1] = val1 if val1 > val2 else val2

            next_mask = 0
            for i in range(N):
                if next_dp[i + 1] > next_dp[i]:
                    next_mask |= (1 << i)

            counts[next_mask] = counts.get(next_mask, 0) + 1

        trans_counts[mask] = list(counts.items())

    # DP over M steps
    dp_state = [0] * num_states
    dp_state[0] = 1

